@using sv_bc437e17461849389bb32adf48581923.Services
@inject ISettingsService SettingsService

<div class="section-card">
    <h2>Notifications</h2>

    @if (_loading)
    {
        <p class="loading-text">Loading preferences…</p>
    }
    else
    {
        <div class="toggle-group">
            <label class="toggle-row">
                <span class="toggle-label">Email Notifications</span>
                <span class="toggle-switch">
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span class="slider"></span>
                </span>
            </label>

            <label class="toggle-row">
                <span class="toggle-label">Push Notifications</span>
                <span class="toggle-switch">
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span class="slider"></span>
                </span>
            </label>

            <label class="toggle-row">
                <span class="toggle-label">Weekly Digest</span>
                <span class="toggle-switch">
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span class="slider"></span>
                </span>
            </label>
        </div>

        @if (_channels.Count > 0)
        {
            <div class="channels-section">
                <h3>Muted Channels</h3>
                <ul class="channel-list">
                    @foreach (var channel in _channels)
                    {
                        <li class="channel-item">
                            <label>
                                <input type="checkbox"
                                       checked="@_mutedChannels.Contains(channel)"
                                       @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                                <span>@channel</span>
                            </label>
                        </li>
                    }
                </ul>
            </div>
        }

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync">Save Preferences</button>
        </div>

        @if (_showSuccess)
        {
            <div class="success-toast">✓ Preferences saved successfully!</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _showSuccess;

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _channels = [];
    private HashSet<string> _mutedChannels = [];

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = [.. prefs.MutedChannels];

        // Build the full channel list from muted channels.
        // In a real app this would come from a separate API.
        _channels = [.. prefs.MutedChannels.Order()];
        _loading = false;
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var prefs = new NotificationPrefs(
            _emailNotifications,
            _pushNotifications,
            _weeklyDigest,
            [.. _mutedChannels]);

        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _showSuccess = true;
        _ = HideToastAfterDelayAsync();
    }

    private async Task HideToastAfterDelayAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

