@namespace sv_bc437e17461849389bb32adf48581923.Components.Settings

<div class="password-panel">
    <button class="panel-toggle" @onclick="() => _expanded = !_expanded">
        <span>🔑 Change Password</span>
        <span class="chevron @(_expanded ? "open" : "")">▶</span>
    </button>

    @if (_expanded)
    {
        <div class="panel-body">
            <div class="form-group">
                <label for="current-pw">Current Password</label>
                <input id="current-pw" type="password" @bind="_currentPassword" />
            </div>

            <div class="form-group">
                <label for="new-pw">New Password</label>
                <input id="new-pw" type="password" @bind="_newPassword" />
            </div>

            <div class="form-group">
                <label for="confirm-pw">Confirm Password</label>
                <input id="confirm-pw" type="password" @bind="_confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(_error))
            {
                <div class="error-message">@_error</div>
            }

            @if (_showSuccess)
            {
                <div class="success-message">✓ Password updated successfully!</div>
            }

            <button class="btn-primary" @onclick="UpdatePasswordAsync" disabled="@_saving">
                @(_saving ? "Updating…" : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public EventCallback<(string Current, string New)> OnPasswordChange { get; set; }

    private bool _expanded;
    private bool _saving;
    private bool _showSuccess;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _error;

    private async Task UpdatePasswordAsync()
    {
        _error = null;
        _showSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _error = "Current password is required.";
            return;
        }

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _error = "New password is required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _error = "New password and confirmation do not match.";
            return;
        }

        _saving = true;

        try
        {
            await OnPasswordChange.InvokeAsync((_currentPassword, _newPassword));
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _showSuccess = true;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }
}

