@namespace sv_bc437e17461849389bb32adf48581923.Components.Settings
@using sv_bc437e17461849389bb32adf48581923.Services
@inject ISettingsService SettingsService

<div class="section-card">
    <h2>Profile</h2>

    @if (_loading)
    {
        <p class="loading-text">Loading profile…</p>
    }
    else
    {
        <div class="avatar-area">
            @if (!string.IsNullOrWhiteSpace(_avatarUrl))
            {
                <img src="@_avatarUrl" alt="Avatar preview" class="avatar-image" />
            }
            else
            {
                <div class="avatar-placeholder">No Avatar</div>
            }
            <span class="avatar-url" title="@_avatarUrl">@_avatarUrl</span>
        </div>

        <div class="form-group">
            <label for="profile-name">Display Name</label>
            <input id="profile-name" type="text" @bind="_displayName" />
        </div>

        <div class="form-group">
            <label for="profile-email">Email</label>
            <input id="profile-email" type="email" @bind="_email" />
        </div>

        <div class="form-group">
            <label for="profile-bio">Bio</label>
            <textarea id="profile-bio" @bind="_bio" rows="4"></textarea>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync">Save Changes</button>
            <button class="btn-secondary" @onclick="Discard">Discard Changes</button>
        </div>

        @if (_showSuccess)
        {
            <div class="success-toast">✓ Profile saved successfully!</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _showSuccess;
    private UserProfile? _savedProfile;

    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _avatarUrl = "";

    protected override async Task OnInitializedAsync()
    {
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _bio = profile.Bio;
        _avatarUrl = profile.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _showSuccess = true;
        _ = HideToastAfterDelayAsync();
    }

    private async Task HideToastAfterDelayAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void Discard()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }

        _showSuccess = false;
    }
}

