@using sv_bc437e17461849389bb32adf48581923.Services

<div class="sessions-section">
    <h3>Active Sessions</h3>

    @if (Sessions.Count == 0)
    {
        <p class="no-sessions">No active sessions.</p>
    }
    else
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn-revoke" @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }
</div>

@if (_sessionToRevoke is not null)
{
    <div class="modal-backdrop" @onclick="CancelRevoke">
        <div class="modal-dialog" @onclick:stopPropagation>
            <h4>Revoke Session</h4>
            <p>
                Are you sure you want to revoke the session on
                <strong>@_sessionToRevoke.Device</strong>
                from <strong>@_sessionToRevoke.Location</strong>?
            </p>
            <div class="modal-actions">
                <button class="btn-danger" @onclick="ConfirmRevokeAsync">Revoke</button>
                <button class="btn-cancel" @onclick="CancelRevoke">Cancel</button>
            </div>
        </div>
    </div>
}

@code {
    [Parameter, EditorRequired]
    public List<ActiveSession> Sessions { get; set; } = [];

    [Parameter]
    public string? CurrentSessionId { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevoke { get; set; }

    private ActiveSession? _sessionToRevoke;

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevoke.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }
}
"}

