.section-card {
    background: #fff;
    border: 1px solid #e9ecef;
    border-radius: 8px;
    padding: 1.5rem 2rem;
}

.section-card h2 {
    margin: 0 0 1.5rem;
    font-size: 1.4rem;
    color: #212529;
}

.loading-text {
    color: #6c757d;
    font-style: italic;
}

.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    margin-bottom: 1.5rem;
}

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    cursor: pointer;
    transition: background-color 0.15s;
}

.toggle-row:hover {
    background: #f8f9fa;
}

.toggle-label {
    font-size: 0.95rem;
    color: #212529;
}

.toggle-switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    inset: 0;
    background: #ced4da;
    border-radius: 24px;
    transition: background 0.2s;
    cursor: pointer;
}

.slider::before {
    content: "";
    position: absolute;
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background: #fff;
    border-radius: 50%;
    transition: transform 0.2s;
}

.toggle-switch input:checked + .slider {
    background: #0d6efd;
}

.toggle-switch input:checked + .slider::before {
    transform: translateX(20px);
}

.channels-section h3 {
    font-size: 1rem;
    margin: 0 0 0.75rem;
    color: #495057;
}

.channel-list {
    list-style: none;
    padding: 0;
    margin: 0 0 1.5rem;
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.channel-item label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0.75rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    color: #495057;
}

.channel-item label:hover {
    background: #f8f9fa;
}

.channel-item input[type="checkbox"] {
    accent-color: #0d6efd;
}

.button-group {
    margin-top: 1.25rem;
}

.btn-primary {
    padding: 0.5rem 1.25rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.15s;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.success-toast {
    margin-top: 1rem;
    padding: 0.6rem 1rem;
    background: #d1e7dd;
    color: #0f5132;
    border-radius: 6px;
    font-size: 0.9rem;
    animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

