toolArgs.file_text:
.password-panel {
    border: 1px solid #e9ecef;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-toggle {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 0.85rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
    color: #212529;
    transition: background-color 0.15s;
}

.panel-toggle:hover {
    background: #e9ecef;
}

.chevron {
    font-size: 0.7rem;
    transition: transform 0.2s;
}

.chevron.open {
    transform: rotate(90deg);
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #e9ecef;
    animation: slideDown 0.2s ease;
}

@keyframes slideDown {
    from { opacity: 0; transform: translateY(-8px); }
    to { opacity: 1; transform: translateY(0); }
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 500;
    font-size: 0.9rem;
    color: #495057;
}

.form-group input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-group input:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.15);
}

.error-message {
    padding: 0.5rem 0.75rem;
    margin-bottom: 0.75rem;
    background: #f8d7da;
    color: #842029;
    border-radius: 6px;
    font-size: 0.9rem;
}

.success-message {
    padding: 0.5rem 0.75rem;
    margin-bottom: 0.75rem;
    background: #d1e7dd;
    color: #0f5132;
    border-radius: 6px;
    font-size: 0.9rem;
}

.btn-primary {
    padding: 0.5rem 1.25rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-primary:disabled {
    opacity: 0.65;
    cursor: not-allowed;
}

