@using sv_bc437e17461849389bb32adf48581923.Services

<div class="sessions-section">
    <h3>Active Sessions</h3>

    @if (Sessions.Count == 0)
    {
        <p class="no-sessions">No active sessions.</p>
    }
    else
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn-revoke" @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }
</div>

@if (_sessionToRevoke is not null)
{
    <div class="modal-backdrop" @onclick="CancelRevoke">
        <div class="modal-dialog" @onclick:stopPropagation>
            <h4>Revoke Session</h4>
            <p>
                Are you sure you want to revoke the session on
                <strong>@_sessionToRevoke.Device</strong>
                from <strong>@_sessionToRevoke.Location</strong>?
            </p>
            <div class="modal-actions">
                <button class="btn-danger" @onclick="ConfirmRevokeAsync">Revoke</button>
                <button class="btn-cancel" @onclick="CancelRevoke">Cancel</button>
            </div>
        </div>
    </div>
}

@code {
    [Parameter, EditorRequired]
    public List<ActiveSession> Sessions { get; set; } = [];

    [Parameter]
    public string? CurrentSessionId { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevoke { get; set; }

    private ActiveSession? _sessionToRevoke;

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevoke.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }
}

.sessions-section h3 {
    font-size: 1rem;
    margin: 0 0 0.75rem;
    color: #495057;
}

.no-sessions {
    color: #6c757d;
    font-style: italic;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th {
    text-align: left;
    padding: 0.6rem 0.75rem;
    border-bottom: 2px solid #dee2e6;
    font-weight: 600;
    color: #495057;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.sessions-table td {
    padding: 0.6rem 0.75rem;
    border-bottom: 1px solid #e9ecef;
    color: #212529;
}

.sessions-table tbody tr:hover {
    background: #f8f9fa;
}

.btn-revoke {
    padding: 0.3rem 0.75rem;
    background: #fff;
    color: #dc3545;
    border: 1px solid #dc3545;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background-color 0.15s, color 0.15s;
}

.btn-revoke:hover {
    background: #dc3545;
    color: #fff;
}

.current-badge {
    display: inline-block;
    padding: 0.2rem 0.6rem;
    background: #d1e7dd;
    color: #0f5132;
    border-radius: 4px;
    font-size: 0.8rem;
    font-weight: 500;
}

/* Confirmation modal */
.modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.45);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    border-radius: 10px;
    padding: 1.5rem 2rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.2);
}

.modal-dialog h4 {
    margin: 0 0 0.75rem;
    font-size: 1.15rem;
}

.modal-dialog p {
    margin: 0 0 1.25rem;
    color: #495057;
    font-size: 0.95rem;
    line-height: 1.5;
}

.modal-actions {
    display: flex;
    gap: 0.75rem;
    justify-content: flex-end;
}

.btn-danger {
    padding: 0.45rem 1rem;
    background: #dc3545;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-cancel {
    padding: 0.45rem 1rem;
    background: #fff;
    color: #495057;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
}

.btn-cancel:hover {
    background: #f8f9fa;
}

