@namespace sv_bc437e17461849389bb32adf48581923.Components.Settings
@using sv_bc437e17461849389bb32adf48581923.Services
@inject ISettingsService SettingsService

<div class="section-card">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <p class="loading-text">Loading appearance settings…</p>
    }
    else
    {
        <div class="option-group">
            <h3>Theme</h3>
            <div class="radio-group">
                @foreach (var theme in _themes)
                {
                    <label class="radio-option @(_theme == theme.Value ? "selected" : "")">
                        <input type="radio" name="theme" value="@theme.Value"
                               checked="@(_theme == theme.Value)"
                               @onchange="() => _theme = theme.Value" />
                        <span>@theme.Label</span>
                    </label>
                }
            </div>
        </div>

        <div class="option-group">
            <h3>Font Size</h3>
            <div class="radio-group">
                @foreach (var size in _fontSizes)
                {
                    <label class="radio-option @(_fontSize == size.Value ? "selected" : "")">
                        <input type="radio" name="fontSize" value="@size.Value"
                               checked="@(_fontSize == size.Value)"
                               @onchange="() => _fontSize = size.Value" />
                        <span>@size.Label</span>
                    </label>
                }
            </div>
        </div>

        <div class="option-group">
            <h3>Language</h3>
            <select class="language-select" @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang.Value">@lang.Label</option>
                }
            </select>
        </div>

        <div class="option-group">
            <label class="toggle-row">
                <span class="toggle-label">Compact Mode</span>
                <span class="toggle-switch">
                    <input type="checkbox" @bind="_compactMode" />
                    <span class="slider"></span>
                </span>
            </label>
        </div>

        <div class="preview-section">
            <h3>Preview</h3>
            <div class="preview-box @GetPreviewClasses()">
                <div class="preview-header">Dashboard</div>
                <p class="preview-text">
                    This is how your interface will look with the selected settings.
                </p>
                <div class="preview-items">
                    <div class="preview-item">Item 1</div>
                    <div class="preview-item">Item 2</div>
                    <div class="preview-item">Item 3</div>
                </div>
            </div>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync">Save</button>
        </div>

        @if (_showSuccess)
        {
            <div class="success-toast">✓ Appearance settings saved!</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _showSuccess;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    private static readonly (string Value, string Label)[] _themes =
        [("Light", "☀️ Light"), ("Dark", "🌙 Dark"), ("System", "💻 System")];

    private static readonly (string Value, string Label)[] _fontSizes =
        [("Small", "Small"), ("Medium", "Medium"), ("Large", "Large")];

    private static readonly (string Value, string Label)[] _languages =
    [
        ("en", "English"),
        ("es", "Español"),
        ("fr", "Français"),
        ("de", "Deutsch"),
        ("ja", "日本語"),
        ("zh", "中文"),
    ];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{_theme.ToLowerInvariant()} font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _showSuccess = true;
        _ = HideToastAfterDelayAsync();
    }

    private async Task HideToastAfterDelayAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

