toolArgs.file_text:
.section-card {
    background: #fff;
    border: 1px solid #e9ecef;
    border-radius: 8px;
    padding: 1.5rem 2rem;
}

.section-card h2 {
    margin: 0 0 1.5rem;
    font-size: 1.4rem;
    color: #212529;
}

.loading-text {
    color: #6c757d;
    font-style: italic;
}

.option-group {
    margin-bottom: 1.5rem;
}

.option-group h3 {
    font-size: 1rem;
    margin: 0 0 0.6rem;
    color: #495057;
}

.radio-group {
    display: flex;
    gap: 0.5rem;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.5rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
    transition: border-color 0.15s, background-color 0.15s;
}

.radio-option:hover {
    background: #f8f9fa;
}

.radio-option.selected {
    border-color: #0d6efd;
    background: #e7f1ff;
    color: #0d6efd;
    font-weight: 500;
}

.radio-option input[type="radio"] {
    display: none;
}

.language-select {
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.95rem;
    min-width: 200px;
    background: #fff;
}

.language-select:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.15);
}

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    cursor: pointer;
    border: 1px solid #e9ecef;
}

.toggle-row:hover {
    background: #f8f9fa;
}

.toggle-label {
    font-size: 0.95rem;
    color: #212529;
}

.toggle-switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    inset: 0;
    background: #ced4da;
    border-radius: 24px;
    transition: background 0.2s;
    cursor: pointer;
}

.slider::before {
    content: "";
    position: absolute;
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background: #fff;
    border-radius: 50%;
    transition: transform 0.2s;
}

.toggle-switch input:checked + .slider {
    background: #0d6efd;
}

.toggle-switch input:checked + .slider::before {
    transform: translateX(20px);
}

/* Live preview */
.preview-section {
    margin-bottom: 1.5rem;
}

.preview-section h3 {
    font-size: 1rem;
    margin: 0 0 0.6rem;
    color: #495057;
}

.preview-box {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 1.25rem;
    transition: all 0.3s ease;
}

.preview-header {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin: 0 0 0.75rem;
    line-height: 1.5;
}

.preview-items {
    display: flex;
    gap: 0.5rem;
}

.preview-item {
    padding: 0.4rem 0.75rem;
    border: 1px solid currentColor;
    border-radius: 4px;
    opacity: 0.7;
}

/* Theme variants */
.preview-box.theme-light {
    background: #ffffff;
    color: #212529;
    border-color: #dee2e6;
}

.preview-box.theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #3a3a4a;
}

.preview-box.theme-system {
    background: #f0f0f5;
    color: #333;
    border-color: #c0c0d0;
}

/* Font size variants */
.preview-box.font-small {
    font-size: 0.8rem;
}

.preview-box.font-medium {
    font-size: 0.95rem;
}

.preview-box.font-large {
    font-size: 1.15rem;
}

/* Compact mode */
.preview-box.compact {
    padding: 0.6rem 0.85rem;
}

.preview-box.compact .preview-header {
    margin-bottom: 0.25rem;
}

.preview-box.compact .preview-text {
    margin-bottom: 0.35rem;
}

.preview-box.compact .preview-items {
    gap: 0.25rem;
}

.preview-box.compact .preview-item {
    padding: 0.2rem 0.5rem;
}

.button-group {
    margin-top: 1.25rem;
}

.btn-primary {
    padding: 0.5rem 1.25rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.success-toast {
    margin-top: 1rem;
    padding: 0.6rem 1rem;
    background: #d1e7dd;
    color: #0f5132;
    border-radius: 6px;
    font-size: 0.9rem;
    animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

